"use client";
import{useRef,useState,useTransition}from"react";import{createClient}from"@/lib/supabase/client";import{reviewVendorDocumentAction,uploadVendorDocumentAction}from"@/app/actions/vendor-documents";
type Doc={id:string;document_type:string;title:string;document_number:string|null;issued_on:string|null;expires_on:string|null;file_name:string|null;file_size_bytes:number|null;status:string;version:number;rejection_reason:string|null;created_at:string};
export function VendorDocumentsPanel({societyId,vendorId,documents,canUpload,canReview}:{societyId:string;vendorId:string;documents:Doc[];canUpload:boolean;canReview:boolean}){const[fileRef,setFileRef]=useState<Doc|null>(null);const[formOpen,setFormOpen]=useState(false);const[inputFile,setInputFile]=useState<File|null>(null);const[message,setMessage]=useState("");const[pending,startTransition]=useTransition();const formRef=useRef<HTMLFormElement>(null);const input="w-full rounded border border-[#333] bg-[#171717] px-3 py-2 text-sm text-text-primary";async function upload(fd:FormData){if(!inputFile)return setMessage("Select a document file.");if(inputFile.size>20*1024*1024)return setMessage("File size must be 20 MB or less.");const client=createClient();const ext=inputFile.name.split(".").pop()??"bin";const path=`${societyId}/vendors/${vendorId}/${crypto.randomUUID()}.${ext}`;const digest=await crypto.subtle.digest("SHA-256",await inputFile.arrayBuffer());const checksum=Array.from(new Uint8Array(digest)).map(b=>b.toString(16).padStart(2,"0")).join("");const{error}=await client.storage.from("society-documents").upload(path,inputFile,{upsert:false});if(error)return setMessage(error.message);startTransition(async()=>{const result=await uploadVendorDocumentAction({vendorId,documentType:String(fd.get("type")),title:String(fd.get("title")),documentNumber:String(fd.get("number")??""),issuedOn:String(fd.get("issuedOn")??""),expiresOn:String(fd.get("expiresOn")??""),storagePath:path,fileName:inputFile.name,mimeType:inputFile.type,fileSize:inputFile.size,checksumSha256:checksum,replacesDocumentId:fileRef?.id});if(!result.success){await client.storage.from("society-documents").remove([path]);setMessage(result.error);}else{setMessage(fileRef?"Replacement uploaded for verification.":"Vendor document uploaded for verification.");setFormOpen(false);setFileRef(null);setInputFile(null);formRef.current?.reset();}});}function review(id:string,decision:"VERIFIED"|"REJECTED"){const reason=decision==="REJECTED"?window.prompt("Reason for rejection")??"":"";if(decision==="REJECTED"&&!reason.trim())return;startTransition(async()=>{const r=await reviewVendorDocumentAction({documentId:id,decision,reason});setMessage(r.success?`Document ${decision.toLowerCase()}.`:r.error);});}return <section className="queue-section"><div className="flex items-center justify-between border-b border-[#333] px-5 py-4"><div><h2 className="font-semibold text-text-primary">Compliance documents</h2><p className="text-xs text-[#9CA3AF]">Licences, tax, insurance, banking and statutory records</p></div>{canUpload&&<button onClick={()=>{setFileRef(null);setFormOpen(true)}} className="rounded bg-[#10B981] px-3 py-2 text-xs text-white">Upload document</button>}</div>{message&&<p role="status" className="m-4 rounded border border-[#333] p-3 text-sm text-[#D1D5DB]">{message}</p>}{formOpen&&<form ref={formRef} action={upload} className="grid gap-3 border-b border-[#333] p-5 md:grid-cols-2"><h3 className="font-semibold text-text-primary md:col-span-2">{fileRef?`Replace ${fileRef.title}`:"Add vendor document"}</h3><input name="type" required placeholder="Document type, e.g. GST" defaultValue={fileRef?.document_type??""} className={input}/><input name="title" required placeholder="Title" defaultValue={fileRef?.title??""} className={input}/><input name="number" placeholder="Document number" defaultValue={fileRef?.document_number??""} className={input}/><input type="file" required accept=".pdf,.doc,.docx,.xls,.xlsx,.png,.jpg,.jpeg" onChange={e=>setInputFile(e.target.files?.[0]??null)} className={input}/><label className="text-xs text-[#9CA3AF]">Issued on<input name="issuedOn" type="date" defaultValue={fileRef?.issued_on??""} className={`${input} mt-1`}/></label><label className="text-xs text-[#9CA3AF]">Expires on<input name="expiresOn" type="date" defaultValue={fileRef?.expires_on??""} className={`${input} mt-1`}/></label><div className="flex justify-end gap-2 md:col-span-2"><button type="button" onClick={()=>{setFormOpen(false);setFileRef(null)}} className="rounded border border-[#444] px-3 py-2 text-xs text-[#D1D5DB]">Cancel</button><button disabled={pending} className="rounded bg-[#10B981] px-3 py-2 text-xs text-white">Upload for verification</button></div></form>}{documents.length===0?<p className="p-8 text-center text-sm text-[#6B7280]">No vendor documents uploaded.</p>:documents.map(d=><article key={d.id} className="flex flex-wrap items-center justify-between gap-3 border-b border-[#292929] px-5 py-4"><div><p className="text-sm font-medium text-text-primary">{d.title} <span className="text-xs text-[#6B7280]">v{d.version}</span></p><p className="text-xs text-[#9CA3AF]">{d.document_type} · {d.document_number??"No number"} · {d.expires_on?`expires ${new Date(d.expires_on).toLocaleDateString("en-IN")}`:"no expiry"}</p>{d.rejection_reason&&<p className="text-xs text-[#EF4444]">{d.rejection_reason}</p>}</div><div className="flex items-center gap-2"><span className="text-xs" style={{color:d.status==="VERIFIED"?"#10B981":d.status==="REJECTED"?"#EF4444":"#F59E0B"}}>{d.status}</span><a href={`/api/vendors/documents/${d.id}`} target="_blank" className="text-xs text-[#38BDF8] underline">View</a>{canUpload&&!['REPLACED'].includes(d.status)&&<button onClick={()=>{setFileRef(d);setFormOpen(true)}} className="text-xs text-[#38BDF8] underline">Replace</button>}{canReview&&d.status==="UPLOADED"&&<><button disabled={pending} onClick={()=>review(d.id,"VERIFIED")} className="text-xs text-[#10B981] underline">Verify</button><button disabled={pending} onClick={()=>review(d.id,"REJECTED")} className="text-xs text-[#EF4444] underline">Reject</button></>}</div></article>)}</section>}
